+            </div>
+          </div>
+        </div>
+      </section>
+    </main>
+
+    <script>
+      const form = document.getElementById("support-form");
+      const statusMessage = document.getElementById("form-status");
+
+      const fields = {
+        fullName: {
+          input: document.getElementById("fullName"),
+          error: document.getElementById("fullName-error"),
+          validate(value) {
+            if (!value.trim()) {
+              return "Error: Enter your full name.";
+            }
+
+            if (value.trim().length < 2) {
+              return "Error: Full name must be at least 2 characters.";
+            }
+
+            return "";
+          }
+        },
+        email: {
+          input: document.getElementById("email"),
+          error: document.getElementById("email-error"),
+          validate(value) {
+            const trimmed = value.trim();
+
+            if (!trimmed) {
+              return "Error: Enter your email address.";
+            }
+
+            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            if (!emailPattern.test(trimmed)) {
+              return "Error: Enter a valid email address like name@example.com.";
+            }
+
+            return "";
+          }
+        },
+        phone: {
+          input: document.getElementById("phone"),
+          error: document.getElementById("phone-error"),
+          validate(value) {
+            const trimmed = value.trim();
+
+            if (!trimmed) {
+              return "";
+            }
+
+            const phonePattern = /^\+?[0-9()\-\s.]{7,20}$/;
+            if (!phonePattern.test(trimmed)) {
+              return "Error: Enter a phone number in a format like (555) 123-4567.";
+            }
+
+            return "";
+          }
+        }
+      };
+
+      function setFieldState(fieldConfig, message) {
+        const wrapper = fieldConfig.input.closest(".form-field");
+        const isInvalid = Boolean(message);
+
+        fieldConfig.input.setAttribute("aria-invalid", String(isInvalid));
+        wrapper.dataset.invalid = isInvalid ? "true" : "false";
+        fieldConfig.error.textContent = message;
+      }
+
+      function validateField(fieldConfig) {
+        const message = fieldConfig.validate(fieldConfig.input.value);
+        setFieldState(fieldConfig, message);
+        return !message;
+      }
+
+      Object.values(fields).forEach((fieldConfig) => {
+        fieldConfig.input.addEventListener("blur", () => {
+          validateField(fieldConfig);
+        });
+
+        fieldConfig.input.addEventListener("input", () => {
+          if (fieldConfig.input.getAttribute("aria-invalid") === "true") {
+            validateField(fieldConfig);
+          } else if (statusMessage.textContent) {
+            statusMessage.textContent = "";
+          }
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        statusMessage.textContent = "";
+
+        let firstInvalidField = null;
+
+        Object.values(fields).forEach((fieldConfig) => {
+          const isValid = validateField(fieldConfig);
+
+          if (!isValid && !firstInvalidField) {
+            firstInvalidField = fieldConfig.input;
+          }
+        });
+
+        if (firstInvalidField) {
+          firstInvalidField.focus();
+          return;
+        }
+
+        statusMessage.textContent = "Your support request is ready to send.";
+        form.reset();
+
+        Object.values(fields).forEach((fieldConfig) => {
+          setFieldState(fieldConfig, "");
+        });
+      });
+    </script>
+  </body>
+</html>
