        font-weight: 600;
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2rem, 4vw, 3.2rem);
        line-height: 1.05;
      }

      .lede,
      .copy-list,
      .form-intro,
      .required-note,
      .helper-text,
      .error-message,
      .status-message {
        margin: 0;
      }

      .lede {
        max-width: 34ch;
        font-size: 1.02rem;
        color: rgba(239, 246, 255, 0.86);
      }

      .copy-list {
        list-style: none;
        padding: 0;
        margin-top: 1.75rem;
        display: grid;
        gap: 1rem;
      }

      .copy-list li {
        padding: 1rem 1.1rem;
        border-radius: 18px;
