      .required-note {
        margin-bottom: 1.5rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      form {
        display: grid;
        gap: 1.2rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-weight: 600;
      }

      .required-indicator {
        color: var(--error);
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        padding: 0.85rem 1rem;
        border: 1px solid #cbd5e1;
        border-radius: 14px;
        background: #fff;
        color: var(--text);
        font: inherit;
        transition:
          border-color 0.2s ease,
          box-shadow 0.2s ease,
          transform 0.2s ease;
      }

      input::placeholder {
        color: #94a3b8;
      }

      input:hover {
        border-color: #94a3b8;
      }

      input:focus-visible,
      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.18);
        border-color: var(--primary);
      }

      .helper-text {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .error-message {
        min-height: 1.25rem;
        color: var(--error);
        font-size: 0.95rem;
      }

      .form-field[data-invalid="true"] input {
        border-color: var(--error);
        background: var(--error-soft);
      }

      button {
        min-height: 3.35rem;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.4rem;
        background: linear-gradient(135deg, var(--primary) 0%, #4f46e5 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition:
          transform 0.2s ease,
          box-shadow 0.2s ease,
          background 0.2s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 32px rgba(37, 99, 235, 0.24);
        background: linear-gradient(135deg, var(--primary-dark) 0%, #4338ca 100%);
      }

      .status-message {
        min-height: 1.5rem;
        font-weight: 600;
        color: var(--success);
      }

      @media (max-width: 860px) {
        .support-layout {
